package com.berling.marketplace.config\n\nimport io.github.jan.supabase.SupabaseClient\nimport io.github.jan.supabase.createSupabaseClient\nimport io.github.jan.supabase.postgrest.Postgrest\nimport io.github.jan.supabase.realtime.Realtime\nimport io.github.jan.supabase.storage.Storage\n\n/**\n * Final Supabase Configuration with all features wired\n */\nobject SupabaseConfigFinal {\n\n    // Supabase credentials\n    private const val SUPABASE_URL = \"https://fkeuioagahwqgpqjuwqj.supabase.co\"\n    private const val SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZrZXVpb2FnYWh3cWdwcWp1d3FqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzkxOTE2NzgsImV4cCI6MjA5NDc2NzY3OH0.rRPejxJ4lVae57Y5IYoBA1dSYCWB24jSVxymZe7bqow\"\n    private const val SUPABASE_PROJECT_ID = \"fkeuioagahwqgpqjuwqj\"\n\n    // Table names\n    const val TABLE_USERS = \"users\"\n    const val TABLE_PRODUCTS = \"products\"\n    const val TABLE_REVIEWS = \"reviews\"\n    const val TABLE_REVIEW_REPLIES = \"review_replies\"\n    const val TABLE_FOLLOWS = \"follows\"\n    const val TABLE_NOTIFICATIONS = \"notifications\"\n    const val TABLE_REPORTS = \"reports\"\n    const val TABLE_BANS = \"bans\"\n    const val TABLE_KYC_APPLICATIONS = \"kyc_applications\"\n    const val TABLE_DEVICE_ACCOUNTS = \"device_accounts\"\n    const val TABLE_CONVERSATIONS = \"conversations\"\n    const val TABLE_MESSAGES = \"messages\"\n    const val TABLE_BLOCKED_USERS = \"blocked_users\"\n    const val TABLE_RATE_LIMITS = \"rate_limits\"\n    const val TABLE_FAVORITES = \"favorites\"\n    const val TABLE_ACTIVITIES = \"activities\"\n    const val TABLE_SELLER_RATINGS = \"seller_ratings\"\n\n    // Storage buckets\n    const val BUCKET_PRODUCT_IMAGES = \"product-images\"\n    const val BUCKET_USER_AVATARS = \"user-avatars\"\n    const val BUCKET_KYC_DOCUMENTS = \"kyc-documents\"\n\n    /**\n     * Initialize Supabase client\n     */\n    fun initializeSupabaseClient(): SupabaseClient {\n        return createSupabaseClient(\n            supabaseUrl = SUPABASE_URL,\n            supabaseKey = SUPABASE_ANON_KEY\n        ) {\n            install(Postgrest)\n            install(Realtime)\n            install(Storage)\n        }\n    }\n\n    /**\n     * Get Supabase URL\n     */\n    fun getSupabaseUrl(): String = SUPABASE_URL\n\n    /**\n     * Get Supabase anon key\n     */\n    fun getSupabaseAnonKey(): String = SUPABASE_ANON_KEY\n\n    /**\n     * Get Supabase project ID\n     */\n    fun getSupabaseProjectId(): String = SUPABASE_PROJECT_ID\n\n    /**\n     * Get all table names\n     */\n    fun getAllTableNames(): List<String> = listOf(\n        TABLE_USERS,\n        TABLE_PRODUCTS,\n        TABLE_REVIEWS,\n        TABLE_REVIEW_REPLIES,\n        TABLE_FOLLOWS,\n        TABLE_NOTIFICATIONS,\n        TABLE_REPORTS,\n        TABLE_BANS,\n        TABLE_KYC_APPLICATIONS,\n        TABLE_DEVICE_ACCOUNTS,\n        TABLE_CONVERSATIONS,\n        TABLE_MESSAGES,\n        TABLE_BLOCKED_USERS,\n        TABLE_RATE_LIMITS,\n        TABLE_FAVORITES,\n        TABLE_ACTIVITIES,\n        TABLE_SELLER_RATINGS\n    )\n\n    /**\n     * Get all storage buckets\n     */\n    fun getAllStorageBuckets(): List<String> = listOf(\n        BUCKET_PRODUCT_IMAGES,\n        BUCKET_USER_AVATARS,\n        BUCKET_KYC_DOCUMENTS\n    )\n\n    /**\n     * Get REST API endpoint for table\n     */\n    fun getTableEndpoint(tableName: String): String {\n        return \"$SUPABASE_URL/rest/v1/$tableName\"\n    }\n\n    /**\n     * Get storage URL for bucket\n     */\n    fun getStorageBucketUrl(bucketName: String): String {\n        return \"$SUPABASE_URL/storage/v1/object/public/$bucketName\"\n    }\n\n    /**\n     * Get realtime subscription URL\n     */\n    fun getRealtimeUrl(): String {\n        return \"wss://$SUPABASE_PROJECT_ID.supabase.co/realtime/v1\"\n    }\n\n    /**\n     * Verify Supabase configuration\n     */\n    fun verifyConfiguration(): Boolean {\n        return SUPABASE_URL.isNotEmpty() &&\n                SUPABASE_ANON_KEY.isNotEmpty() &&\n                SUPABASE_PROJECT_ID.isNotEmpty()\n    }\n\n    /**\n     * Get configuration summary\n     */\n    fun getConfigurationSummary(): String {\n        return buildString {\n            append(\"Supabase Configuration Summary\\n\")\n            append(\"==============================\\n\")\n            append(\"URL: $SUPABASE_URL\\n\")\n            append(\"Project ID: $SUPABASE_PROJECT_ID\\n\")\n            append(\"Tables: ${getAllTableNames().size}\\n\")\n            append(\"Storage Buckets: ${getAllStorageBuckets().size}\\n\")\n            append(\"Configuration Valid: ${verifyConfiguration()}\\n\")\n        }\n    }\n}\n
